    def can_place_district(self, x: int, y: int, district: str,
                          city_center: Tuple[int, int],
                          placed: Dict[str, Tuple[int, int]]) -> bool:
        """Check if a district can be placed at a location"""
        if (x, y) == city_center:
            return False
        if (x, y) in placed.values():
            return False
        if self.map.hex_distance(x, y, city_center[0], city_center[1]) > 3:
            return False

        if district == 'HARBOR':
            if not self.map.is_water(x, y):
                return False
            neighbors = self.map.get_neighbors(x, y)
            has_land = any(self.map.is_land(nx, ny) for nx, ny in neighbors)
            if not has_land:
                return False
        else:
            if not self.map.is_land(x, y):
                return False

        if self.map.has_mountain(x, y):
            return False

        return True

    def calculate_adjacency_bonus(self, x: int, y: int, district: str,
                                  city_center: Tuple[int, int],
                                  placed: Dict[str, Tuple[int, int]]) -> int:
