        bonus = 0
        neighbors = self.map.get_neighbors(x, y)

        if district == 'CAMPUS':
            # +1 per adjacent mountain
            for nx, ny in neighbors:
                if self.map.has_mountain(nx, ny):
                    bonus += 1
            # +1 per adjacent rainforest/jungle
            for nx, ny in neighbors:
                if self.map.has_feature(nx, ny, 'FEATURE_JUNGLE'):
                    bonus += 1
            # +1 per 2 adjacent districts (NOT city center)
            adjacent_districts = sum(1 for pos in placed.values() if (pos[0], pos[1]) in neighbors)
            bonus += adjacent_districts // 2

        elif district == 'HOLY_SITE':
