                    bonus += 1
            # +1 per 2 adjacent districts
            adjacent_districts = sum(1 for pos in placed.values() if (pos[0], pos[1]) in neighbors)
            bonus += adjacent_districts // 2

        elif district == 'THEATER_SQUARE':
            # +1 per 2 adjacent districts
            adjacent_districts = sum(1 for pos in placed.values() if (pos[0], pos[1]) in neighbors)
            bonus += adjacent_districts // 2

        elif district == 'COMMERCIAL_HUB':
            # +1 per adjacent river
            if self.map.has_river(x, y):
                bonus += 1
            # +2 per adjacent harbor
            for district_name, pos in placed.items():
                if district_name == 'HARBOR' and (pos[0], pos[1]) in neighbors:
                    bonus += 2
            # +1 per 2 adjacent districts
            adjacent_districts = sum(1 for pos in placed.values() if (pos[0], pos[1]) in neighbors)
