    def optimize_greedy(self, city_center: Tuple[int, int]) -> Tuple[Dict, Dict, int]:
        """Greedy optimization: place districts to maximize immediate benefit"""
        workable = [(x, y) for x in range(self.map.width) for y in range(self.map.height)
                   if self.map.hex_distance(x, y, city_center[0], city_center[1]) <= 3]

        districts_to_try = ['CAMPUS', 'HOLY_SITE', 'COMMERCIAL_HUB', 'HARBOR',
                           'INDUSTRIAL_ZONE', 'THEATER_SQUARE', 'ENTERTAINMENT_COMPLEX']

        best_total = 0
        best_placements = {}
        best_bonuses = {}

        # Try all combinations up to max districts
        for num_districts in range(1, min(self.max_districts + 1, len(districts_to_try) + 1)):
            for district_combo in combinations(districts_to_try, num_districts):
                for district_order in permutations(district_combo):
                    placements = {}
                    bonuses = {}

                    for district in district_order:
                        best_bonus = -1
                        best_pos = None

                        for tile_pos in workable:
                            if self.can_place_district(tile_pos[0], tile_pos[1], district,
                                                      city_center, placements):
