                                    best_bonus = bonus
                                    best_pos = tile_pos

                        if best_pos:
                            placements[district] = best_pos
                            bonuses[district] = best_bonus

                    # Recalculate all bonuses to account for district-to-district adjacency
                    final_bonuses = {}
                    for district, pos in placements.items():
                        final_bonuses[district] = self.calculate_adjacency_bonus(
                            pos[0], pos[1], district, city_center, placements
                        )

                    total = sum(final_bonuses.values())
                    if total > best_total:
                        best_total = total
                        best_placements = placements.copy()
                        best_bonuses = final_bonuses.copy()

        return best_placements, best_bonuses, best_total


def solve_scenario(scenario_path: str, output_path: str):
    """Solve a Civ6 optimization scenario"""
    with open(scenario_path, 'r') as f:
        scenario = json.load(f)

    print(f"Solving scenario: {scenario['id']}")
    print(f"Cities: {scenario['num_cities']}, Population: {scenario['population']}")
    print(f"Max districts: {scenario['population'] // 3}")

    # Load map
    map_file = f"/data/{scenario['map_file']}"
    civ_map = Civ6Map(map_file)
    print(f"Map size: {civ_map.width}x{civ_map.height}")

    # Create optimizer
    optimizer = DistrictOptimizer(civ_map, scenario['num_cities'], scenario['population'])

    # Find best city location
    print("Finding optimal city location...")
    city_center = optimizer.find_best_city_location()
    print(f"City center: {city_center}")

    # Optimize district placements
    print("Optimizing district placements...")
    placements, bonuses, total = optimizer.optimize_greedy(city_center)

    print(f"\nOptimal solution:")
    print(f"City center: {city_center}")
    for district, pos in sorted(placements.items()):
        print(f"  {district}: {pos} (bonus: {bonuses[district]})")
    print(f"Total adjacency: {total}")

    # Verify total
    calculated_total = sum(bonuses.values())
    assert calculated_total == total, f"Total mismatch: {calculated_total} != {total}"

    # Create output
    result = {
        "city_center": list(city_center),
        "placements": {k: list(v) for k, v in placements.items()},
        "adjacency_bonuses": bonuses,
        "total_adjacency": total
    }

    # Write output
    with open(output_path, 'w') as f:
        json.dump(result, f, indent=2)

    print(f"\nSolution written to {output_path}")


